/**
 * JSON-LD (@graph) for the home page: WebSite, ProfilePage, Person and one
 * VideoObject per published video16x9 project with an entry in
 * content/video-meta.json (generated by scripts/video-meta.mjs).
 */
import videoMeta from "@/content/video-meta.json";
import { R2_BASE } from "./media";
import type { Project } from "./projects";

const SITE   = "https://www.huskymillion.com";
const PERSON = { "@id": `${SITE}/#person` };

/** director is only set for these projects */
const DIRECTED = new Set(["kottur", "riders-rights", "woz"]);

/** Credits with these labels become productionCompany / sponsor, not contributors */
const AGENCY_LABELS = new Set(["Agency"]);
const CLIENT_LABELS = new Set(["Client", "Clients"]);

const META: Record<string, { duration: string; uploadDate: string }> = videoMeta;

const splitNames = (names: string) => names.split(",").map((n) => n.trim()).filter(Boolean);
const orgs = (names: string[]) => {
  const list = names.map((name) => ({ "@type": "Organization", name }));
  return list.length === 1 ? list[0] : list;
};

function videoObject(p: Project) {
  const meta    = META[p.slug];
  const credits = p.credits ?? [];

  const contributor: object[] = [];
  if (p.role) contributor.push({ "@type": "Role", roleName: p.role, contributor: PERSON });
  for (const c of credits) {
    if (AGENCY_LABELS.has(c.label) || CLIENT_LABELS.has(c.label)) continue;
    const people = splitNames(c.names).map((name) => ({ "@type": "Person", name }));
    contributor.push({ "@type": "Role", roleName: c.label, contributor: people.length === 1 ? people[0] : people });
  }

  const agencies = credits.filter((c) => AGENCY_LABELS.has(c.label)).flatMap((c) => splitNames(c.names));
  const clients  = credits.filter((c) => CLIENT_LABELS.has(c.label)).flatMap((c) => splitNames(c.names));
  const producer = p.slug === "kottur" ? ["köttur"] : agencies;

  return {
    "@type":        "VideoObject",
    "@id":          `${SITE}/#video-${p.slug}`,
    name:           `${p.name} — ${p.tagline}`,
    description:    p.description,
    thumbnailUrl:   `${R2_BASE}/projects/${p.slug}/poster.jpg`,
    contentUrl:     `${R2_BASE}/projects/${p.slug}/hero.mp4`,
    uploadDate:     meta.uploadDate,
    duration:       meta.duration,
    url:            `${SITE}/#case-${p.slug}`,
    ...(p.award && { award: p.award }),
    ...(DIRECTED.has(p.slug) && { director: PERSON }),
    ...(contributor.length > 0 && { contributor }),
    ...(producer.length > 0 && { productionCompany: orgs(producer) }),
    ...(p.slug !== "kottur" && clients.length > 0 && { sponsor: orgs(clients) }),
  };
}

export function buildSchema(projects: Project[]) {
  return {
    "@context": "https://schema.org",
    "@graph": [
      { "@type": "WebSite", "@id": `${SITE}/#website`,
        url: SITE, name: "Pascal Pfohl — huskymillion", inLanguage: "en" },
      { "@type": "ProfilePage", "@id": `${SITE}/#profile`,
        url: SITE, isPartOf: { "@id": `${SITE}/#website` },
        mainEntity: PERSON },
      { "@type": "Person", "@id": `${SITE}/#person`,
        name: "Pascal Pfohl", alternateName: "huskymillion",
        url: SITE, image: `${SITE}/og-image.jpg`,
        jobTitle: "Art Direction for Moving Image, Content Production & Motion Design",
        homeLocation: { "@type": "Place", name: "Zürich, Switzerland" },
        email: "mailto:pascal@kottur.de",
        knowsAbout: ["art direction for moving image", "Art Direction Bewegtbild", "motion design", "content production",
          "video production", "Videoproduktion", "direction", "camera", "editing", "Schnitt", "colour grading",
          "sound design", "social-first content", "documentary film"],
        sameAs: ["https://www.instagram.com/huskymillion/", "https://www.linkedin.com/in/pascal-pfohl-950a70173/"] },
      ...projects.filter((p) => p.layout === "video16x9" && META[p.slug]).map(videoObject),
    ],
  };
}
